#!/usr/bin/env node
// Generated by ajch_agent_framework 0.2.0. Edit the source named in .claude/kit.lock.json, then npm run kit.
/**
 * PreToolUse hook: block writes to files the agent must not edit by hand.
 * Rules come from kit-config.json next to this file, written by the framework's
 * render step:
 *   - protected: the vertical's own read-only paths, and files synced from
 *     another repo (edit upstream and re-sync, or the next sync overwrites it)
 *   - generated: files rendered from kit/ (edit the source, then npm run kit)
 * Exit 2 blocks the tool call and tells the agent why.
 */
import { readFileSync } from 'fs';
import { join, dirname } from 'path';
import { fileURLToPath } from 'url';

const here = dirname(fileURLToPath(import.meta.url));
let config = { protected: [], generated: {} };
try { config = JSON.parse(readFileSync(join(here, 'kit-config.json'), 'utf-8')); } catch { /* no config: allow */ }

let input = '';
process.stdin.on('data', (c) => { input += c; });
process.stdin.on('end', () => {
  let path = '';
  try { path = (JSON.parse(input).tool_input?.file_path ?? '').replace(/\\/g, '/'); } catch { process.exit(0); }
  const rule = config.protected.find((p) => new RegExp(p.pattern).test(path));
  if (rule) { process.stderr.write(`Blocked: ${path} — ${rule.reason}.\n`); process.exit(2); }
  const gen = Object.keys(config.generated).find((g) => path.endsWith('/' + g));
  if (gen) {
    process.stderr.write(`Blocked: ${path} is generated by ajch_agent_framework from ${config.generated[gen]}. Edit that source, then run npm run kit.\n`);
    process.exit(2);
  }
  process.exit(0);
});
